$lessons[] = ['level' => 'pre-intermediate', 'topic' => 'The Psychology of Regret', 'background_key' => 'minimal-dark',
    'warmup' => V("Let's talk about regret. Do you have any regrets, and how do you deal with them?", 'Давайте поговорим о сожалении. У вас есть какие-то сожаления и как вы с ними справляетесь?', 'Өкініш туралы сөйлесейік. Сізде қандай да бір өкініштер бар ма және онымен қалай күресесіз?'),
    'vocab' => [V('regret', 'сожаление', 'өкініш'), V('hindsight', 'взгляд назад', 'кейін қарау'), V('missed opportunity', 'упущенная возможность', 'жіберілген мүмкіндік'), V('closure', 'завершённость', 'аяқталу'), V('what if', 'что если', 'егер...болса ше'), V('forgiveness', 'прощение', 'кешірім'), V('acceptance', 'принятие', 'қабылдау'), V('reflection', 'размышление', 'ой елеу'), V('turning point', 'поворотный момент', 'бетбұрыс сәті'), V('second chance', 'второй шанс', 'екінші мүмкіндік')],
    'questions' => [
        V('Do you have any regrets in your life?', 'У вас есть какие-то сожаления в жизни?', 'Өміріңізде қандай да бір өкініштеріңіз бар ма?'),
        V('Do you think regret is a useful emotion, or a harmful one?', 'Как вы думаете, сожаление — полезная эмоция, или вредная?', 'Өкініш пайдалы эмоция ма, әлде зиянды ма деп ойлайсыз ба?'),
        V('Do you often think "what if" about past decisions?', 'Вы часто думаете "что если" о прошлых решениях?', 'Өткен шешімдер туралы жиі "егер... болса ше" деп ойлайсыз ба?'),
        V('Have you ever forgiven yourself for a past mistake?', 'Вы когда-нибудь прощали себя за прошлую ошибку?', 'Өткен қатеңіз үшін өзіңізді кешірдіңіз бе?'),
        V('Do you think people regret things they did more, or things they didn\'t do?', 'Как вы думаете, люди больше жалеют о том, что сделали, или о том, чего не сделали?', 'Адамдар жасаған нәрселеріне көбірек өкінеді ме, әлде жасамаған нәрселеріне ме деп ойлайсыз ба?'),
        V('Have you ever gotten a second chance after regretting something?', 'У вас когда-нибудь был второй шанс после сожаления о чём-то?', 'Бір нәрсеге өкінгеннен кейін екінші мүмкіндігіңіз болды ма?'),
        V('Do you think reflecting on regrets helps you grow?', 'Как вы думаете, размышление о сожалениях помогает вам расти?', 'Өкініштер туралы ойлану өсуіңізге көмектеседі деп ойлайсыз ба?'),
        V('Is there a missed opportunity you still think about?', 'Есть ли упущенная возможность, о которой вы всё ещё думаете?', 'Әлі де ойлайтын жіберілген мүмкіндігіңіз бар ма?'),
        V('Do you think talking about regrets with others helps find closure?', 'Как вы думаете, разговор о сожалениях с другими помогает найти завершённость?', 'Өкініштер туралы басқалармен сөйлесу аяқталуды табуға көмектеседі деп ойлайсыз ба?'),
        V('Was there a turning point in your life caused by a regret?', 'Был ли в вашей жизни поворотный момент, вызванный сожалением?', 'Өміріңізде өкініштен туындаған бетбұрыс сәті болды ма?'),
        V('Do older people regret different things than younger people, in your opinion?', 'По-вашему, пожилые люди жалеют о других вещах, чем молодые?', 'Сіздің ойыңызша, егде адамдар жастардан басқа нәрселерге өкінеді ме?'),
        V('Do you think it is possible to live completely without regret?', 'Как вы думаете, возможно ли жить совсем без сожалений?', 'Мүлдем өкінішсіз өмір сүру мүмкін бе деп ойлайсыз ба?'),
